export RUN_ID_CLEANED=$(echo $ZEALT_RUN_ID | tr '-' '_')
echo "Table name: products_$RUN_ID_CLEANED"
mkdir -p /home/user/myproject/convex
cat <<EOF > /home/user/myproject/convex/schema.ts
import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";

export default defineSchema({
  products_${RUN_ID_CLEANED}: defineTable({
    name: v.string(),
    price: v.number(),
  }),
});
EOF

export RUN_ID_CLEANED=$(echo $ZEALT_RUN_ID | tr '-' '_')
cat <<EOF > /home/user/myproject/convex/products.ts
import { query } from "./_generated/server";

export const list = query({
  args: {},
  handler: async (ctx) => {
    return await ctx.db.query("products_${RUN_ID_CLEANED}").collect();
  },
});
EOF

cat <<EOF > /home/user/myproject/convex/http.ts
import { httpRouter } from "convex/server";
import { httpAction } from "./_generated/server";
import { api } from "./_generated/api";

const http = httpRouter();

http.route({
  path: "/exportProducts",
  method: "GET",
  handler: httpAction(async (ctx, request) => {
    const records = await ctx.runQuery(api.products.list);
    return new Response(JSON.stringify(records), {
      status: 200,
      headers: {
        "Content-Type": "application/json",
      },
    });
  }),
});

export default http;
EOF

